use std :: fs ; use std :: path :: Path ; use clap :: Parser ; use serde_json ; use num_bigint :: BigUint ; use cargo_vendormod :: group_atlas :: { GroupAtlas , GroupFamily , ClassicalLieType , TwistedLieType , SporadicGroup , n } ; use cargo_vendormod :: visualization :: { AtlasRenderer , AtlasConfig } ; # [doc = " Print summary statistics to console"] fn print_summary_stats (atlas : & GroupAtlas) { println ! ("\n📊 Atlas Summary:") ; println ! ("   Total Groups: {}" , atlas . groups . len ()) ; println ! ("   Total Compositions: {}" , atlas . compositions . len ()) ; println ! ("   Families: {}" , count_families (atlas)) ; println ! ("   Order Range: {} to {}" , get_min_order (atlas) , get_max_order (atlas)) ; let cyclic_count = count_groups_by_family (atlas , "Cyclic") ; let alternating_count = count_groups_by_family (atlas , "Alternating") ; let lie_count = count_groups_by_family (atlas , "LieType") ; let sporadic_count = count_groups_by_family (atlas , "Sporadic") ; let twisted_count = count_groups_by_family (atlas , "TwistedLieType") ; println ! ("   Cyclic: {}" , cyclic_count) ; println ! ("   Alternating: {}" , alternating_count) ; println ! ("   Lie Type: {}" , lie_count) ; println ! ("   Sporadic: {}" , sporadic_count) ; println ! ("   Twisted Lie: {}" , twisted_count) ; }